// Inlined by esbuild's `define` at build time (see esbuild.config.mjs) — the
// extension has no Node runtime, so this is a build-time constant, not a
// real process.env. Declared narrowly here instead of pulling in
// @types/node, which would shadow DOM's URL/URLSearchParams with Node's.
declare const process: {
  env: {
    PARIKSHA_BACKEND_URL: string;
  };
};
